import { groupNum1 } from "../../constants/groups";
import Title from "../../components/Title/Title";
import { useState } from "react";

import "./Group1.css";

export function Group1() {
  const [sort, setSort] = useState(groupNum1);

  let name = false;
  function sortName() {
    if (!name) {
      let sortedNameAZ = sort.toSorted((a, b) => a.name.localeCompare(b.name));
      setSort(sortedNameAZ);
      name = true;
    } else if (name) {
      let sortedNameZA = sort.toSorted((a, b) => b.name.localeCompare(a.name));
      setSort(sortedNameZA);
      name = false;
    }

  }

  return (
    <div className="mainG1">
      <Title sortName={sortName} />
      {sort.map((elm) => {
        return (
          <div className="box" key={elm.id}>
            <img src={elm.image} alt="worker" />
            <p>{elm.name}</p>
            <p>{elm.surname}</p>
            <p>{elm.age}</p>
            <p>{elm.gender}</p>
            <p>{elm.profession}</p>
          </div>
        );
      })}
    </div>
  );
}
